    "rowId": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Унікальний ідентифікатор рядка, який потрібно оновити." } },
    "before": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Якщо надано, новостворений рядок буде розміщено перед рядком із наданим id." } }
